#!/usr/bin/env python3
"""Analyze YAML data: compute statistics, group by categories, generate summary report."""

import sys
import yaml
import statistics
from collections import defaultdict
from pathlib import Path


def load_yaml(path):
    with open(path) as f:
        return yaml.safe_load(f)


def compute_stats(values):
    if len(values) < 2:
        return {"count": len(values), "mean": values[0] if values else 0}
    return {
        "count": len(values),
        "mean": round(statistics.mean(values), 4),
        "median": round(statistics.median(values), 4),
        "std_dev": round(statistics.stdev(values), 4),
        "min": min(values),
        "max": max(values),
    }


def extract_numeric_fields(records):
    """Find all numeric fields across records and group their values."""
    field_values = defaultdict(list)
    for record in records:
        if not isinstance(record, dict):
            continue
        for key, val in record.items():
            if isinstance(val, (int, float)):
                field_values[key].append(val)
    return field_values


def group_by(records, key):
    """Group records by a categorical field."""
    groups = defaultdict(list)
    for record in records:
        if isinstance(record, dict) and key in record:
            groups[record[key]].append(record)
    return dict(groups)


def generate_report(data, category_field=None):
    lines = []
    lines.append("=" * 60)
    lines.append("YAML DATA ANALYSIS REPORT")
    lines.append("=" * 60)

    # Normalize: accept a list directly or a dict with a list under a key
    if isinstance(data, list):
        records = data
    elif isinstance(data, dict):
        # Pick the first key whose value is a list
        for v in data.values():
            if isinstance(v, list):
                records = v
                break
        else:
            records = [data]
    else:
        return "Error: unsupported YAML structure"

    lines.append(f"\nTotal records: {len(records)}")

    # --- Overall statistics for numeric fields ---
    field_values = extract_numeric_fields(records)
    if field_values:
        lines.append("\n" + "-" * 60)
        lines.append("OVERALL NUMERIC STATISTICS")
        lines.append("-" * 60)
        for field, values in sorted(field_values.items()):
            stats = compute_stats(values)
            lines.append(f"\n  {field}:")
            for k, v in stats.items():
                lines.append(f"    {k:>8}: {v}")

    # --- Group-by analysis ---
    if category_field and records:
        groups = group_by(records, category_field)
        if groups:
            lines.append("\n" + "-" * 60)
            lines.append(f"GROUPED BY '{category_field}' ({len(groups)} groups)")
            lines.append("-" * 60)
            for group_name, group_records in sorted(groups.items(), key=lambda x: str(x[0])):
                lines.append(f"\n  [{group_name}] ({len(group_records)} records)")
                grp_field_values = extract_numeric_fields(group_records)
                for field, values in sorted(grp_field_values.items()):
                    stats = compute_stats(values)
                    lines.append(f"    {field}: mean={stats['mean']}, median={stats['median']}, std_dev={stats.get('std_dev', 'N/A')}")

    lines.append("\n" + "=" * 60)
    return "\n".join(lines)


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <data.yaml> [category_field]")
        print(f"  category_field: optional field name to group records by")
        sys.exit(1)

    path = sys.argv[1]
    category = sys.argv[2] if len(sys.argv) > 2 else None

    data = load_yaml(path)
    report = generate_report(data, category_field=category)
    print(report)


if __name__ == "__main__":
    main()
